/**
 * Synthetic Demo Event Provider
 *
 * Provides deterministic and simulated security events strictly for
 * controlled academic / viva demonstrations.
 *
 * PROVENANCE REQUIREMENT:
 * Every record generated by this provider is strictly tagged:
 * dataSource: 'SYNTHETIC_DEMO'
 * isRealData: false
 *
 * Never represented as real external data.
 */

import { SecurityEvent, Asset } from '../types/schemas';

const SYNTHETIC_ATTACK_PATTERNS = [
  {
    category: 'Exploit Public-Facing App' as const,
    severity: 'CRITICAL' as const,
    description: '[SIMULATED DEMO] Probe payload targeting Spring4Shell ClassLoader in HTTP POST headers',
    cve: 'CVE-2022-22965',
    rule: 'DEMO-SIM-EXPLOIT-01',
  },
  {
    category: 'Brute Force' as const,
    severity: 'HIGH' as const,
    description: '[SIMULATED DEMO] Simulated high-frequency credential stuffing targeting customer login endpoint',
    rule: 'DEMO-SIM-AUTH-BURST',
  },
  {
    category: 'Remote Code Execution' as const,
    severity: 'CRITICAL' as const,
    description: '[SIMULATED DEMO] Simulated command injection payload targeting PAN-OS GlobalProtect portal',
    cve: 'CVE-2024-3400',
    rule: 'DEMO-SIM-CMD-INJECT',
  },
  {
    category: 'SQL Injection' as const,
    severity: 'HIGH' as const,
    description: '[SIMULATED DEMO] Union-based SQL injection pattern targeting reporting microservice',
    rule: 'DEMO-SIM-SQLI-03',
  },
  {
    category: 'Command & Control' as const,
    severity: 'CRITICAL' as const,
    description: '[SIMULATED DEMO] Simulated TLS heartbeat pattern matching known Cobalt Strike beacon profile',
    rule: 'DEMO-SIM-C2-BEACON',
  },
  {
    category: 'Privilege Escalation' as const,
    severity: 'HIGH' as const,
    description: '[SIMULATED DEMO] Simulated Kerberoast ticket request pattern for sensitive service account',
    rule: 'DEMO-SIM-KERBEROAST',
  },
  {
    category: 'Reconnaissance' as const,
    severity: 'LOW' as const,
    description: '[SIMULATED DEMO] Synthetic port scan sweep across external DMZ boundary',
    rule: 'DEMO-SIM-PORT-SCAN',
  },
];

const SIMULATED_ATTACKER_IPS = [
  '198.51.100.99',
  '203.0.113.42',
  '192.0.2.115',
  '198.51.100.17',
  '203.0.113.88',
  '192.0.2.77',
];

export class SyntheticDemoProvider {
  private counter = 1000;

  /**
   * Generates a single synthetic demo event for live demonstration
   */
  generateLiveEvent(targetAssets: Asset[]): SecurityEvent {
    this.counter++;
    const pattern = SYNTHETIC_ATTACK_PATTERNS[Math.floor(Math.random() * SYNTHETIC_ATTACK_PATTERNS.length)];
    const attackerIp = SIMULATED_ATTACKER_IPS[Math.floor(Math.random() * SIMULATED_ATTACKER_IPS.length)];
    const asset = targetAssets.length > 0
      ? targetAssets[Math.floor(Math.random() * targetAssets.length)]
      : {
          id: 'AST-PROD-WEB-01',
          name: 'prod-edge-web01.internal',
          ipAddress: '10.0.4.15',
          criticality: 'CRITICAL' as const,
        };

    return {
      id: `SIM-EVT-${this.counter}`,
      timestamp: new Date().toISOString(),
      sourceIp: attackerIp,
      destinationIp: asset.ipAddress,
      assetId: asset.id,
      assetName: asset.name,
      assetCriticality: asset.criticality,
      attackCategory: pattern.category,
      severity: pattern.severity,
      description: pattern.description,
      relatedCveId: pattern.cve,
      detectionRule: pattern.rule,
      status: 'ACTIVE',
      dataSource: 'SYNTHETIC_DEMO',
      isRealData: false,
    };
  }

  /**
   * Generates a batch of baseline synthetic events for initial demo setup
   */
  generateBaselineDemoEvents(assets: Asset[], count = 10): SecurityEvent[] {
    const list: SecurityEvent[] = [];
    const baseTime = Date.now() - 3600000; // 1 hour ago

    for (let i = 0; i < count; i++) {
      const pattern = SYNTHETIC_ATTACK_PATTERNS[i % SYNTHETIC_ATTACK_PATTERNS.length];
      const asset = assets[i % assets.length] || {
        id: 'AST-PROD-WEB-01',
        name: 'prod-edge-web01.internal',
        ipAddress: '10.0.4.15',
        criticality: 'CRITICAL' as const,
      };

      const eventTime = new Date(baseTime + i * 300000).toISOString();

      list.push({
        id: `DEMO-BASELINE-${100 + i}`,
        timestamp: eventTime,
        sourceIp: SIMULATED_ATTACKER_IPS[i % SIMULATED_ATTACKER_IPS.length],
        destinationIp: asset.ipAddress,
        assetId: asset.id,
        assetName: asset.name,
        assetCriticality: asset.criticality,
        attackCategory: pattern.category,
        severity: pattern.severity,
        description: pattern.description,
        relatedCveId: pattern.cve,
        detectionRule: pattern.rule,
        status: i % 3 === 0 ? 'RESOLVED' : i % 2 === 0 ? 'CONTAINED' : 'ACTIVE',
        dataSource: 'SYNTHETIC_DEMO',
        isRealData: false,
      });
    }

    return list;
  }
}

export const syntheticDemoProvider = new SyntheticDemoProvider();
